const result = $input.first().json;
const workflowData = $getWorkflowStaticData('global');
if (!workflowData.handoffNotificationLedger || typeof workflowData.handoffNotificationLedger !== 'object' || Array.isArray(workflowData.handoffNotificationLedger) || typeof result.notificationStorageKey !== 'string') {
  return [{ json: {
    ...result,
    decision: 'failure',
    errorCode: 'notification_ledger_unavailable',
    errorContext: 'handoff',
  } }];
}
workflowData.handoffNotificationLedger[result.notificationStorageKey] = {
  status: 'succeeded',
  succeededAt: new Date().toISOString(),
};
return [{ json: { ...result, notificationDuplicate: false } }];

const wrapper = $input.first().json ?? {};
const event = wrapper.event;
const isObject = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const isId = (value) => typeof value === 'string' && value.length >= 1 && value.length <= 64;
const invalid = {
  valid: false,
  eventId: isId(event?.eventId) ? event.eventId : '',
  organizationId: isId(event?.organizationId) ? event.organizationId : '',
  runId: isId(event?.runId) ? event.runId : '',
  errorCode: 'invalid_handoff_event',
  errorContext: 'handoff',
};
if (!isObject(event) || event.type !== 'conversation.handoff_requested' || !isId(event.eventId) || !isId(event.organizationId) || !isId(event.runId) || !isObject(event.payload)) {
  return [{ json: invalid }];
}
const payload = event.payload;
if (payload.eventId !== event.eventId || payload.organizationId !== event.organizationId || !isId(payload.conversationId) || !Array.isArray(payload.recipients) || payload.recipients.length < 1 || payload.recipients.length > 50) {
  return [{ json: invalid }];
}
const recipients = [];
const seen = new Set();
for (const recipient of payload.recipients) {
  if (!isObject(recipient) || !isId(recipient.userId) || typeof recipient.name !== 'string' || typeof recipient.email !== 'string' || !['OWNER', 'ADMIN', 'AGENT'].includes(recipient.role)) {
    return [{ json: invalid }];
  }
  if (!seen.has(recipient.userId)) {
    seen.add(recipient.userId);
    recipients.push({
      userId: recipient.userId,
      name: recipient.name.slice(0, 100),
      email: recipient.email.slice(0, 254),
      role: recipient.role,
    });
  }
}
if (payload.assignedAgent !== null && payload.assignedAgent !== undefined && (!isObject(payload.assignedAgent) || !isId(payload.assignedAgent.userId) || typeof payload.assignedAgent.name !== 'string' || typeof payload.assignedAgent.email !== 'string' || !['OWNER', 'ADMIN', 'AGENT'].includes(payload.assignedAgent.role))) {
  return [{ json: invalid }];
}
const assignedAgent = isObject(payload.assignedAgent)
  ? {
      userId: payload.assignedAgent.userId,
      name: payload.assignedAgent.name.slice(0, 100),
      email: payload.assignedAgent.email.slice(0, 254),
      role: payload.assignedAgent.role,
    }
  : null;
const notificationBody = JSON.stringify({
  eventId: event.eventId,
  organizationId: event.organizationId,
  conversationId: payload.conversationId,
  eventType: 'conversation.handoff_requested',
  businessName: String(payload.businessName).slice(0, 100),
  customerName: String(payload.customerName).slice(0, 100),
  conversationUrl: String(payload.conversationUrl).slice(0, 1000),
  requestedAt: String(payload.requestedAt).slice(0, 40),
  assignedAgent,
  recipients,
});
return [{ json: {
  valid: true,
  eventId: event.eventId,
  organizationId: event.organizationId,
  runId: event.runId,
  notificationBody,
  recipientCount: recipients.length,
} }];

const prepared = $input.first().json;
const event = $('Called by event router').first().json.event;
const idempotencyKey = typeof event?.idempotencyKey === 'string' ? event.idempotencyKey : '';
if (!/^[\x21-\x7e]{1,200}$/.test(idempotencyKey)) {
  return [{ json: {
    ...prepared,
    valid: false,
    errorCode: 'invalid_handoff_event',
    errorContext: 'handoff',
  } }];
}
const workflowData = $getWorkflowStaticData('global');
if (!workflowData.handoffNotificationLedger || typeof workflowData.handoffNotificationLedger !== 'object' || Array.isArray(workflowData.handoffNotificationLedger)) {
  workflowData.handoffNotificationLedger = {};
}
const ledger = workflowData.handoffNotificationLedger;
const ledgerNow = Date.now();
const retentionMs = 7 * 24 * 60 * 60 * 1000;
for (const [key, entry] of Object.entries(ledger)) {
  const timestamp = Date.parse(entry?.succeededAt ?? entry?.reservedAt ?? '');
  if (!Number.isFinite(timestamp) || ledgerNow - timestamp > retentionMs) delete ledger[key];
}
const retained = Object.entries(ledger);
if (retained.length >= 10000) {
  retained
    .sort((left, right) => Date.parse(left[1]?.succeededAt ?? left[1]?.reservedAt ?? '') - Date.parse(right[1]?.succeededAt ?? right[1]?.reservedAt ?? ''))
    .slice(0, retained.length - 9999)
    .forEach(([key]) => delete ledger[key]);
}
const storageKey = `event:${prepared.eventId}|key:${idempotencyKey}`;
const existing = workflowData.handoffNotificationLedger[storageKey];
const notificationDuplicate = existing?.status === 'succeeded';
if (!existing) {
  workflowData.handoffNotificationLedger[storageKey] = {
    status: 'reserved',
    reservedAt: new Date().toISOString(),
  };
}
return [{ json: {
  ...prepared,
  notificationKey: idempotencyKey,
  notificationStorageKey: storageKey,
  notificationDuplicate,
} }];

const source = $('Reserve notification idempotency').first().json;
const response = $input.first().json ?? {};
const statusCode = Number(response.statusCode);
if (Number.isInteger(statusCode) && statusCode >= 200 && statusCode < 300) {
  return [{ json: {
    decision: 'success',
    eventId: source.eventId,
    organizationId: source.organizationId,
    runId: source.runId,
    recipientCount: source.recipientCount,
    notificationKey: source.notificationKey,
    notificationStorageKey: source.notificationStorageKey,
  } }];
}
const errorCode = statusCode === 429
  ? 'notification_rate_limited'
  : Number.isInteger(statusCode) && statusCode >= 400 && statusCode < 500
    ? 'notification_rejected'
    : 'notification_unavailable';
return [{ json: {
  decision: 'failure',
  eventId: source.eventId,
  organizationId: source.organizationId,
  runId: source.runId,
  errorCode,
  errorContext: 'handoff',
} }];

const result = $input.first().json;
const callbackTimestamp = Date.now();
const callbackBody = JSON.stringify({
  eventId: result.eventId,
  organizationId: result.organizationId,
  runId: result.runId,
  timestamp: callbackTimestamp,
  status: 'succeeded',
  externalExecutionId: String($execution.id),
  responseMeta: {
    workflow: 'vantix-handoff-alert',
    notifiedRecipients: result.recipientCount,
    duplicate: result.notificationDuplicate === true,
  },
});
return [{ json: { callbackBody, callbackTimestamp: String(callbackTimestamp) } }];
